	victimFinal, err := accCacher.LoadUser(victim)
	require.NoError(t, err)
	_, nftErr := victimFinal.SubInternalKDA(collectionID, assetID)
	require.Error(t, nftErr, "HARM: B holds no NFT for the funds it lost")

	t.Logf("PROVEN: B lost %d KLV (balance %d -> %d), unrecoverable. A gained %d KLV (balance %d -> %d). "+
		"Y-X = %d KLV destroyed/stranded.",
		bidY, fundVictim, balance(victim), bidX, fundAttacker, balance(attacker), bidY-bidX)
